<?php

namespace Database\Seeders;

use App\Models\Question;
use App\Models\Topic;
use Illuminate\Database\Seeder;

class QuestionSeeder extends Seeder
{
    /**
     * Seed sample MCQs per topic (difficulty 1-5) so the adaptive quiz engine
     * and GCE simulation have a usable pool end-to-end. This is a starter set;
     * teacher_verified/admin users extend the bank via the question CRUD API.
     */
    public function run(): void
    {
        foreach ($this->questionBank() as $topicCode => $questions) {
            $topic = Topic::where('code', $topicCode)->first();

            if (! $topic) {
                continue;
            }

            foreach ($questions as $q) {
                Question::updateOrCreate(
                    ['topic_id' => $topic->id, 'stem' => $q['stem']],
                    [
                        'level_id' => $topic->level_id,
                        'type' => 'mcq',
                        'options' => $q['options'],
                        'correct_option' => $q['correct'],
                        'difficulty' => $q['difficulty'],
                        'explanation' => $q['explanation'],
                        'marks' => 1,
                        'is_active' => true,
                    ]
                );
            }
        }
    }

