                $this->q('Which statement best explains why gas exchange surfaces (like alveoli) must remain moist?', ['Moisture blocks oxygen from entering', 'Gases dissolve in the moisture before diffusing across the membrane', 'Moisture prevents diffusion entirely', 'It has no functional importance'], 1, 5, 'Gases must dissolve in a moist film before they can diffuse across cell membranes.'),
            ],
            'OL-EXCRETION' => [
