                $this->q('Urea is formed in the:', ['Kidney', 'Liver', 'Bladder', 'Pancreas'], 1, 1, 'The liver deaminates excess amino acids to form urea.'),
                $this->q('The functional unit of the kidney is the:', ['Neuron', 'Nephron', 'Alveolus', 'Villus'], 1, 2, 'Each kidney contains roughly a million nephrons.'),
                $this->q('Which substance is normally NOT found in healthy urine?', ['Urea', 'Water', 'Glucose', 'Salts'], 2, 3, 'Glucose is normally fully reabsorbed in the nephron.'),
                $this->q('Ultrafiltration in the kidney occurs at the:', ['Loop of Henle', 'Glomerulus', 'Collecting duct', 'Ureter'], 1, 4, 'High blood pressure forces small molecules out of the glomerulus.'),
                $this->q('Reabsorption of water in the nephron is controlled mainly by the hormone:', ['Insulin', 'ADH', 'Adrenaline', 'Testosterone'], 1, 5, 'Antidiuretic hormone regulates collecting duct permeability to water.'),
                $this->q('Excretion is defined as the removal of:', ['Undigested food from the body', 'Metabolic waste products from the body', 'Digested food into the blood', 'Water only'], 1, 1, 'Excretion removes waste products made by the body\'s own metabolism.'),
                $this->q('The two kidneys are connected to the bladder by the:', ['Urethra', 'Ureters', 'Renal artery', 'Renal vein'], 1, 1, 'Ureters carry urine from each kidney down to the bladder.'),
                $this->q('Urine leaves the body through the:', ['Ureter', 'Urethra', 'Renal vein', 'Nephron'], 1, 1, 'The urethra carries urine out of the body from the bladder.'),
                $this->q('Deamination of excess amino acids occurs mainly in the:', ['Kidney', 'Liver', 'Pancreas', 'Stomach'], 1, 2, 'The liver removes the amino group from excess amino acids, forming urea.'),
                $this->q('Which substance is filtered out of the blood at the glomerulus along with urea and water?', ['Red blood cells', 'Glucose (initially)', 'Large plasma proteins', 'White blood cells'], 1, 2, 'Small molecules like glucose pass through, then glucose is reabsorbed later.'),
                $this->q('The renal artery carries blood ___ the kidney, and the renal vein carries blood ___ the kidney.', ['Into; away from', 'Away from; into', 'Into; into', 'Away from; away from'], 0, 2, 'The renal artery supplies the kidney; the renal vein drains it.'),
                $this->q('Selective reabsorption in the nephron occurs mainly at the:', ['Glomerulus', "Bowman's capsule", 'Proximal convoluted tubule', 'Ureter'], 2, 3, 'Useful substances are reabsorbed back into the blood at the proximal tubule.'),
                $this->q('Which of the following is NOT normally filtered at the glomerulus due to its large size?', ['Water', 'Urea', 'Plasma proteins', 'Salts'], 2, 3, 'Plasma proteins are too large to pass through the glomerular filter.'),
