                $this->q('If ADH levels are high, the collecting duct becomes:', ['Less permeable to water, producing dilute urine', 'More permeable to water, producing concentrated urine', 'Completely impermeable to water', 'Permeable to glucose only'], 1, 4, 'High ADH increases water reabsorption, concentrating the urine.'),
                $this->q('Dialysis machines perform the function of the kidney mainly by:', ['Producing hormones', 'Filtering waste products from the blood using a partially permeable membrane', 'Producing red blood cells', 'Digesting proteins'], 1, 4, 'Dialysis mimics kidney filtration using an artificial membrane.'),
                $this->q('Which of the following would increase ADH secretion?', ['Drinking excess water', 'Dehydration (low body water)', 'Eating a large meal', 'Cold weather only'], 1, 4, 'Dehydration triggers more ADH release to conserve water.'),
                $this->q('A patient whose urine contains glucose most likely has a problem with:', ['The glomerulus filtering too little', 'Selective reabsorption in the proximal convoluted tubule (or diabetes affecting blood glucose)', 'The ureter', 'The urethra'], 1, 5, 'Glucose in urine usually indicates reabsorption cannot keep up, often due to diabetes.'),
                $this->q('Explain why alcohol consumption often leads to increased urine production:', ['Alcohol increases ADH secretion', 'Alcohol inhibits ADH secretion, reducing water reabsorption', 'Alcohol has no effect on the kidney', 'Alcohol directly damages the bladder'], 1, 5, 'Less ADH means less water reabsorbed, producing more dilute urine.'),
            ],
            'OL-COORDINATION' => [
                $this->q('The organ system responsible for rapid coordination is the:', ['Endocrine system', 'Nervous system', 'Skeletal system', 'Digestive system'], 1, 1, 'Nerve impulses act much faster than hormones.'),
                $this->q('The part of the brain responsible for balance and coordination is the:', ['Cerebrum', 'Cerebellum', 'Medulla', 'Hypothalamus'], 1, 1, 'The cerebellum fine-tunes movement and posture.'),
                $this->q('A reflex action is:', ['A slow, conscious response', 'A fast, automatic response', 'Controlled by hormones only', 'Only found in plants'], 1, 2, 'Reflexes bypass conscious brain processing for speed.'),
                $this->q('The gap between two neurons is called a:', ['Axon', 'Dendrite', 'Synapse', 'Node'], 2, 3, 'Neurotransmitters cross the synapse to relay the signal.'),
                $this->q('Which hormone is released in response to stress, increasing heart rate?', ['Insulin', 'Adrenaline', 'Oestrogen', 'Testosterone'], 1, 4, 'Adrenaline prepares the body for "fight or flight".'),
                $this->q('Diabetes mellitus is caused by a lack of the hormone:', ['Adrenaline', 'Insulin', 'Thyroxine', 'Progesterone'], 1, 5, 'Insulin deficiency prevents cells from taking up glucose normally.'),
