                $this->q('Neurons that carry impulses from receptors to the CNS are called:', ['Motor neurons', 'Sensory neurons', 'Relay neurons', 'Effector neurons'], 1, 1, 'Sensory neurons carry information from receptors towards the CNS.'),
                $this->q('The gland that produces insulin is the:', ['Thyroid', 'Pancreas', 'Pituitary', 'Adrenal gland'], 1, 1, 'The pancreas contains cells that secrete insulin into the blood.'),
                $this->q('Effectors are structures that:', ['Detect stimuli', 'Carry impulses to the brain', 'Produce a response to a stimulus, e.g. muscles or glands', 'Store hormones'], 2, 2, 'Effectors, like muscles and glands, carry out the response.'),
                $this->q('Hormones are transported around the body in the:', ['Nerves', 'Blood', 'Lymph only', 'Digestive tract'], 1, 2, 'Hormones travel from glands to target organs via the bloodstream.'),
                $this->q('The part of the brain responsible for conscious thought, memory and reasoning is the:', ['Cerebellum', 'Medulla oblongata', 'Cerebrum', 'Spinal cord'], 2, 2, 'The cerebrum handles higher mental functions like thought and memory.'),
                $this->q('Which of the following best describes a reflex arc?', ['Stimulus, receptor, sensory neuron, relay neuron, motor neuron, effector', 'Stimulus, effector, receptor', 'Response, stimulus, receptor', 'Effector, sensory neuron, brain, response'], 0, 3, 'This is the standard pathway followed in a spinal reflex.'),
                $this->q('The pupil reflex, where the pupil constricts in bright light, is an example of:', ['A learned behaviour', 'A reflex action', 'Hormonal control only', 'Voluntary action'], 1, 3, 'The pupil reflex is fast, automatic, and protective.'),
                $this->q('Compared to nervous responses, hormonal responses are typically:', ['Faster and shorter-lived', 'Slower and longer-lasting', 'Identical in speed and duration', 'Not transported at all'], 1, 3, 'Hormones act more slowly but their effects tend to persist longer.'),
                $this->q('Type 2 diabetes is characterised by:', ['No insulin production and immediate onset in childhood only', "The body's cells becoming less responsive to insulin", 'Excess insulin production causing low blood sugar always', 'A viral infection of the pancreas'], 1, 4, 'Type 2 diabetes typically involves insulin resistance in body cells.'),
                $this->q('Adrenaline prepares the body for "fight or flight" by:', ['Lowering heart rate and blood glucose', 'Increasing heart rate, breathing rate and blood glucose release', 'Inducing sleep', 'Slowing digestion increase only'], 1, 4, 'Adrenaline readies the body for rapid action in response to stress.'),
                $this->q('Which of the following is controlled by the autonomic (involuntary) nervous system?', ['Writing with a pen', 'Heart rate and digestion', 'Deciding to walk', 'Speaking'], 1, 4, 'The autonomic nervous system controls involuntary body functions.'),
                $this->q('A person who touches a hot object withdraws their hand before feeling pain consciously. This best demonstrates that:', ['Reflexes bypass the need for conscious brain processing to act quickly', 'Pain is felt before the reflex occurs', 'The reflex arc involves the cerebrum first', 'Hormones caused the response'], 0, 5, 'Reflex arcs act via the spinal cord, faster than conscious brain processing.'),
                $this->q('Long-term, untreated high blood glucose (as in diabetes) can damage blood vessels and nerves because:', ['Glucose is toxic to the pancreas only', 'Persistently high glucose levels cause harmful changes to blood vessel walls and nerve tissue over time', 'It has no long-term effects', 'It only affects eyesight'], 1, 5, 'Chronic high glucose damages blood vessels and nerves throughout the body.'),
            ],
            'OL-REPRODUCTION' => [
                $this->q('The male sex cells are called:', ['Ova', 'Sperm', 'Zygotes', 'Embryos'], 1, 1, 'Sperm are produced in the testes.'),
                $this->q('Fertilisation in humans normally occurs in the:', ['Uterus', 'Ovary', 'Oviduct (Fallopian tube)', 'Vagina'], 2, 1, 'Sperm typically meet the egg in the fallopian tube.'),
                $this->q('The site of implantation of the embryo is the:', ['Ovary', 'Uterus lining', 'Cervix', 'Vagina'], 1, 2, 'The embryo embeds in the endometrium.'),
                $this->q('The placenta functions mainly to:', ['Produce eggs', 'Exchange nutrients and waste between mother and foetus', 'Store sperm', 'Produce milk'], 1, 3, 'It allows diffusion of nutrients/gases without mixing blood directly.'),
                $this->q('Which hormone maintains the uterine lining during pregnancy?', ['Oestrogen', 'Progesterone', 'FSH', 'Testosterone'], 1, 4, 'Progesterone prevents the lining from breaking down.'),
                $this->q('Identical twins result from:', ['Fertilisation of two separate eggs', 'Splitting of one fertilised egg', 'Fertilisation by two sperm', 'A genetic mutation'], 1, 5, 'Splitting produces two genetically identical embryos.'),
                $this->q('The female sex cell is called the:', ['Sperm', 'Ovum (egg)', 'Zygote', 'Embryo'], 1, 1, 'The ovum is the female gamete produced in the ovary.'),
                $this->q('Puberty in males is triggered mainly by increased production of:', ['Oestrogen', 'Testosterone', 'Insulin', 'Adrenaline'], 1, 1, 'Testosterone drives male puberty changes.'),
                $this->q('The fusion of a sperm and an egg is called:', ['Ovulation', 'Fertilisation', 'Implantation', 'Menstruation'], 1, 1, 'Fertilisation is the union of male and female gametes.'),
                $this->q('Ovulation refers to:', ['The release of a mature egg from the ovary', 'The shedding of the uterus lining', 'The fusion of gametes', 'The implantation of an embryo'], 0, 2, 'Ovulation is the release of an egg, usually mid-cycle.'),
                $this->q("The umbilical cord connects the foetus to the:", ['Mother\'s lungs directly', 'Placenta', "Mother's stomach", 'Amniotic sac only'], 1, 2, 'The umbilical cord links the foetus to the placenta for exchange.'),
                $this->q('Amniotic fluid mainly functions to:', ['Provide nutrients to the foetus', 'Cushion and protect the developing foetus', "Remove waste from the mother", 'Produce hormones'], 1, 2, 'Amniotic fluid protects the foetus from physical shocks.'),
                $this->q('Which hormone triggers ovulation at roughly the midpoint of the menstrual cycle?', ['Progesterone', 'A surge in luteinising hormone (LH)', 'Testosterone', 'Insulin'], 1, 3, 'An LH surge triggers the release of the egg from the ovary.'),
                $this->q('If fertilisation does not occur, what happens to the uterus lining?', ['It thickens further', 'It is shed during menstruation', 'It becomes the placenta', 'It turns into an egg'], 1, 3, 'Without pregnancy, the lining breaks down and is shed as menstrual flow.'),
                $this->q('Non-identical (fraternal) twins result from:', ['One egg splitting into two after fertilisation', 'Two separate eggs being fertilised by two different sperm', 'One sperm fertilising two eggs simultaneously by fusion', 'A single zygote dividing unevenly'], 1, 3, 'Two eggs and two sperm produce genetically distinct fraternal twins.'),
                $this->q('The placenta allows exchange of substances between mother and foetus but prevents:', ['Oxygen from crossing', 'Direct mixing of maternal and foetal blood', 'Nutrients from crossing', 'Carbon dioxide from crossing'], 1, 4, 'The placenta keeps the two blood supplies separate while allowing diffusion.'),
                $this->q('Which of the following passes from mother to foetus via the placenta?', ['Only waste products', 'Oxygen and nutrients', 'Only carbon dioxide', 'Only urea'], 1, 4, 'Oxygen and nutrients diffuse from mother to foetus across the placenta.'),
                $this->q('Breast milk is particularly important for a newborn because it provides:', ['Only water', "Antibodies and nutrients suited to the baby's needs", 'Only fat', 'No nutritional value'], 1, 4, 'Breast milk supplies both nutrition and passive immunity.'),
                $this->q('Explain why the placenta is described as having a very large surface area with a thin barrier:', ['To reduce nutrient exchange', 'To maximise efficient diffusion of gases and nutrients between mother and foetus while keeping bloods separate', 'To prevent any exchange at all', 'It has no functional significance'], 1, 5, 'A large area and thin barrier maximise diffusion rate across the placenta.'),
                $this->q('A woman who has her fallopian tubes blocked would most likely experience difficulty with:', ['Menstruation only', 'Fertilisation, since sperm cannot reach the egg', 'Implantation only', 'Milk production'], 1, 5, 'Blocked tubes prevent sperm and egg from meeting for fertilisation.'),
            ],
            'OL-ECOLOGY' => [
                $this->q('A community of organisms interacting with their physical environment is called a(n):', ['Population', 'Ecosystem', 'Habitat', 'Niche'], 1, 1, 'An ecosystem includes biotic communities and abiotic factors.'),
                $this->q('Organisms that make their own food are called:', ['Consumers', 'Decomposers', 'Producers', 'Predators'], 2, 1, 'Producers, mainly plants, convert light energy into chemical energy.'),
                $this->q('The ultimate source of energy for most ecosystems is:', ['The soil', 'The sun', 'Water', 'Wind'], 1, 2, 'Sunlight drives photosynthesis, the base of most food chains.'),
                $this->q('Organisms that break down dead matter, recycling nutrients, are called:', ['Producers', 'Primary consumers', 'Decomposers', 'Herbivores'], 2, 3, 'Decomposers like bacteria and fungi recycle nutrients back to soil.'),
                $this->q('Deforestation is likely to lead to:', ['Increased biodiversity', 'Reduced soil erosion', 'Loss of habitat and reduced biodiversity', 'Increased rainfall'], 2, 4, 'Removing trees destroys habitats many species depend on.'),
                $this->q('In a food chain: grass -> grasshopper -> frog -> snake, the snake is a:', ['Producer', 'Primary consumer', 'Secondary consumer', 'Tertiary consumer'], 3, 5, 'The snake is the fourth trophic level, a tertiary consumer.'),
                $this->q('A group of organisms of the same species living in the same area is called a:', ['Community', 'Population', 'Ecosystem', 'Habitat'], 1, 1, 'A population is all the members of one species in an area.'),
                $this->q('The place where an organism normally lives is called its:', ['Niche', 'Habitat', 'Population', 'Biome'], 1, 1, 'A habitat is the physical place an organism lives.'),
                $this->q('Animals that eat only plants are called:', ['Carnivores', 'Herbivores', 'Omnivores', 'Decomposers'], 1, 1, 'Herbivores feed exclusively on plant material.'),
                $this->q('A food web is best described as:', ['A single food chain', 'Several interconnected food chains in an ecosystem', 'A list of producers only', 'The energy lost as heat'], 1, 2, 'Food webs show the many feeding relationships within an ecosystem.'),
                $this->q('Which of these is an abiotic (non-living) factor in an ecosystem?', ['Predators', 'Temperature', 'Competitors', 'Decomposers'], 1, 2, 'Temperature is a physical, non-living factor affecting organisms.'),
                $this->q('The role an organism plays within its ecosystem, including what it eats and where it lives, is called its:', ['Habitat', 'Niche', 'Population', 'Community'], 1, 2, "An organism's niche describes its full ecological role."),
                $this->q('Energy is lost between trophic levels mainly as:', ['Light', 'Heat, through respiration', 'Sound', 'Chemical energy stored permanently'], 1, 3, 'Respiration releases much of the energy as heat, which is lost from the food chain.'),
                $this->q('A pyramid of numbers or biomass typically becomes narrower at higher trophic levels because:', ['Energy and biomass decrease at each successive level', 'Organisms get bigger at each level only', 'There are always more predators than prey', 'Decomposers remove all energy at once'], 0, 3, 'Less energy and biomass are available as you move up trophic levels.'),
                $this->q('Overfishing is an example of:', ['Natural population control', "Human impact reducing a population's sustainability", 'A natural predator-prey cycle', 'Increased biodiversity'], 1, 3, 'Overfishing removes fish faster than populations can replenish themselves.'),
                $this->q('Which of the following best describes a limiting factor in population growth?', ['A factor that has no effect on population size', 'A factor such as food or space that restricts further population increase', 'Only disease', 'Only predators'], 1, 4, 'Limiting factors cap how large a population can grow.'),
                $this->q('Bioaccumulation of toxins (e.g. pesticides) up a food chain results in:', ['Lower concentrations in top predators', 'Higher concentrations of toxins in top predators than in producers', 'No difference across trophic levels', 'Toxins disappearing entirely'], 1, 4, 'Toxins become more concentrated as they pass up the food chain.'),
                $this->q('Which human activity most directly contributes to global loss of biodiversity through habitat destruction?', ['Recycling', 'Deforestation for agriculture and logging', 'Afforestation', 'Conservation programmes'], 1, 4, 'Deforestation directly destroys habitats needed by many species.'),
                $this->q('In a stable ecosystem, the removal of a top predator would most likely lead to:', ['No change at all', 'An increase in prey population, potentially causing overgrazing and knock-on effects', 'Immediate extinction of all species', 'An increase in producers only, unaffected by other changes'], 1, 5, 'Losing a top predator can trigger a cascade of effects through the food web.'),
                $this->q('Explain why only about 10% of energy is typically transferred from one trophic level to the next:', ['Most energy is used in respiration, movement, and lost as heat, or is in parts not eaten/digested', 'All energy is transferred with none lost', 'Energy is created at each level', 'Producers store 90% of energy permanently'], 0, 5, 'Energy is lost at each level mainly through respiration and incomplete consumption/digestion.'),
            ],
            'AL-CELL' => [
                $this->q('Which organelle is bound by a double membrane and contains its own DNA?', ['Ribosome', 'Mitochondrion', 'Lysosome', 'Golgi apparatus'], 1, 1, 'Mitochondria (and chloroplasts) have their own circular DNA.'),
                $this->q('Rough endoplasmic reticulum is studded with:', ['Lysosomes', 'Ribosomes', 'Peroxisomes', 'Centrioles'], 1, 2, 'Ribosomes on the RER synthesise proteins for secretion.'),
                $this->q('The main function of the Golgi apparatus is to:', ['Synthesise ATP', 'Modify, package and secrete proteins', 'Replicate DNA', 'Digest bacteria'], 1, 3, 'The Golgi processes proteins from the ER into vesicles.'),
                $this->q('Which of the following is a feature of prokaryotic but not eukaryotic cells?', ['Cell membrane', 'Ribosomes', 'Absence of a nuclear envelope', 'Cytoplasm'], 2, 3, 'Prokaryotic DNA lies free in the cytoplasm, not membrane-bound.'),
                $this->q('Electron microscopes have greater resolution than light microscopes mainly because:', ['Electrons have a shorter wavelength than light', 'Electrons are larger than photons', 'Electron microscopes use lenses made of glass', 'Electron microscopes magnify colour better'], 0, 4, 'Shorter wavelength allows finer structures to be resolved.'),
                $this->q('Which combination of organelles would be most abundant in a human pancreatic cell that secretes digestive enzymes?', ['Chloroplasts and vacuoles', 'Rough ER, Golgi apparatus and secretory vesicles', 'Centrioles and lysosomes only', 'Cell wall and plasmodesmata'], 1, 5, 'These organelles form the secretory pathway for protein export.'),
                $this->q('Which organelle is the site of ATP synthesis via oxidative phosphorylation?', ['Golgi apparatus', 'Mitochondrion', 'Lysosome', 'Nucleolus'], 1, 1, 'Oxidative phosphorylation on the inner mitochondrial membrane produces most ATP.'),
                $this->q('The fluid mosaic model describes the structure of the:', ['Nucleus', 'Cell membrane', 'Ribosome', 'Cell wall'], 1, 1, 'The fluid mosaic model describes proteins moving within a lipid bilayer.'),
                $this->q('Centrioles are mainly associated with:', ['Protein synthesis', 'Spindle fibre formation during cell division', 'Lipid synthesis', 'ATP production'], 1, 2, 'Centrioles help organise the spindle apparatus during division.'),
                $this->q('Smooth endoplasmic reticulum is primarily involved in:', ['Protein synthesis', 'Lipid and steroid synthesis', 'ATP production', 'DNA replication'], 1, 2, 'Smooth ER lacks ribosomes and specialises in lipid synthesis.'),
                $this->q('Which structure is found in plant cells but not typically in animal cells?', ['Mitochondria', 'Ribosomes', 'Chloroplasts and a large central vacuole', 'Golgi apparatus'], 2, 2, 'Chloroplasts and a large vacuole are distinctive plant cell features.'),
                $this->q('Lysosomes contain:', ['Hydrolytic (digestive) enzymes', 'Chlorophyll', 'DNA', 'ATP synthase only'], 0, 2, 'Lysosomes break down material using hydrolytic enzymes.'),
                $this->q('The 70S ribosomes found in prokaryotes and mitochondria differ from the 80S ribosomes of the eukaryotic cytoplasm mainly in:', ['Function', 'Size and subunit composition', 'Location only', 'Colour'], 1, 3, '70S and 80S ribosomes differ in their sedimentation coefficient, reflecting size and subunit differences.'),
                $this->q('Which feature is a key piece of evidence for the endosymbiotic theory of mitochondrial origin?', ['Mitochondria have a single membrane', 'Mitochondria contain their own circular DNA and 70S ribosomes similar to bacteria', 'Mitochondria are found only in plants', 'Mitochondria lack an inner membrane'], 1, 3, "This bacterial-like DNA and ribosome type supports mitochondria's bacterial ancestry."),
                $this->q('The cytoskeleton, composed of microtubules and microfilaments, functions mainly to:', ['Store genetic material', 'Provide structural support and enable intracellular transport/movement', 'Produce ATP', 'Digest waste'], 1, 3, 'The cytoskeleton gives cells shape and enables movement of materials within them.'),
                $this->q('Which of the following would be most affected by a mutation preventing Golgi vesicle formation?', ['DNA replication', 'Secretion of proteins such as enzymes and hormones', 'ATP production in mitochondria', 'Photosynthesis'], 1, 4, 'The Golgi packages proteins into vesicles for secretion; disrupting this blocks secretion.'),
                $this->q('Freeze-fracture electron microscopy is particularly useful for studying:', ['DNA sequences', 'The internal structure of membranes', 'Whole organism behaviour', 'Population genetics'], 1, 4, 'Freeze-fracture splits membranes to reveal their internal structure.'),
                $this->q('Which statement about nuclear pores is correct?', ['They prevent all molecules from entering or leaving the nucleus', 'They allow selective exchange of molecules such as mRNA and proteins between nucleus and cytoplasm', 'They are only present in prokaryotes', 'They synthesise ribosomes'], 1, 4, 'Nuclear pores regulate traffic of molecules between nucleus and cytoplasm.'),
                $this->q('A cell showing an unusually high number of mitochondria would most likely be one that:', ['Is metabolically inactive', 'Has a very high energy demand, e.g. a muscle or liver cell', 'Never undergoes respiration', 'Is a red blood cell'], 1, 5, 'Cells with high energy needs contain more mitochondria to meet ATP demand.'),
                $this->q('Compared to light microscopy, transmission electron microscopy allows visualisation of:', ['Only living, moving cells', 'Detailed internal ultrastructure such as organelle membranes, due to much higher resolution', 'Colour differences in stained tissue', 'Nothing beyond what light microscopy shows'], 1, 5, 'TEM\'s much higher resolution reveals fine internal cell structures.'),
            ],
            'AL-BIOMOLECULES' => [
                $this->q('Enzymes are biological catalysts made of:', ['Lipids', 'Proteins', 'Carbohydrates', 'Nucleic acids'], 1, 1, 'Enzymes are globular proteins with a specific active site.'),
                $this->q('The "lock and key" model describes:', ['DNA replication', 'Enzyme-substrate specificity', 'Membrane transport', 'Osmosis'], 1, 2, 'The active site shape complements a specific substrate.'),
                $this->q('An increase in temperature beyond an enzyme\'s optimum usually causes the enzyme to:', ['Work faster indefinitely', 'Denature and lose activity', 'Change substrate specificity', 'Become more stable'], 1, 3, 'Excess heat breaks the bonds maintaining tertiary structure.'),
                $this->q('A competitive inhibitor reduces enzyme activity by:', ['Binding to the active site, blocking the substrate', "Changing the enzyme's active site shape permanently", 'Binding away from the active site only', 'Destroying the substrate'], 0, 3, 'It competes directly with substrate for the active site.'),
                $this->q('Glycosidic bonds join monomers in:', ['Proteins', 'Carbohydrates', 'Lipids', 'Nucleic acids'], 1, 4, 'Glycosidic bonds link monosaccharides into polysaccharides.'),
                $this->q('In an enzyme-catalysed reaction at high substrate concentration, the rate of reaction plateaus because:', ['The enzyme is destroyed', 'All active sites are saturated', 'The substrate becomes inhibitory', 'Temperature drops'], 1, 5, 'Rate becomes limited by enzyme concentration, not substrate.'),
                $this->q('Enzymes work by:', ['Being used up in the reaction', 'Lowering the activation energy of a reaction', 'Increasing the activation energy', 'Stopping reactions permanently'], 1, 1, 'Enzymes speed up reactions by lowering the energy barrier needed.'),
                $this->q('A molecule that an enzyme acts upon is called the:', ['Product', 'Substrate', 'Cofactor', 'Inhibitor'], 1, 1, 'The substrate is the molecule the enzyme binds and converts.'),
                $this->q('Which bond joins amino acids together in a protein?', ['Glycosidic bond', 'Peptide bond', 'Phosphodiester bond', 'Hydrogen bond only'], 1, 1, 'Peptide bonds link amino acids into polypeptide chains.'),
                $this->q('The induced fit model of enzyme action proposes that:', ['The active site is rigid and unchanging', 'The active site changes shape slightly to mould around the substrate', 'Enzymes never bind substrates', "Substrates change the enzyme's primary structure permanently"], 1, 2, 'Induced fit describes a flexible active site adjusting to the substrate.'),
                $this->q('Non-competitive inhibitors reduce enzyme activity by:', ['Binding to the active site directly', "Binding at a site other than the active site, changing the enzyme's shape", 'Increasing substrate concentration', 'Being identical to the substrate'], 1, 2, 'Non-competitive inhibitors distort the active site from elsewhere on the enzyme.'),
                $this->q('The tertiary structure of a protein is maintained mainly by:', ['Peptide bonds only', 'Interactions such as hydrogen bonds, ionic bonds, disulfide bridges and hydrophobic interactions between R groups', 'Glycosidic bonds', 'Phosphodiester bonds'], 1, 2, 'These R-group interactions fold the polypeptide into its 3D shape.'),
                $this->q("Which factor, if increased beyond the optimum, denatures an enzyme by breaking bonds maintaining its tertiary structure?", ['Substrate concentration', 'Temperature', 'Enzyme concentration', 'Product concentration'], 1, 3, 'Excess heat disrupts the bonds holding the enzyme\'s shape.'),
                $this->q('A graph of initial reaction rate against pH for an enzyme typically shows:', ['A straight line increasing indefinitely', 'A peak at the optimum pH, decreasing either side', 'No relationship at all', 'A constant rate regardless of pH'], 1, 3, 'Enzyme activity peaks at its optimum pH and falls away from it.'),
                $this->q('Cofactors are important for some enzymes because they:', ['Are always proteins themselves', 'Are non-protein substances required for the enzyme to function properly', 'Permanently destroy the enzyme', 'Have no functional role'], 1, 3, 'Cofactors assist catalysis but are not proteins themselves.'),
                $this->q('Which best distinguishes competitive from non-competitive inhibition in terms of increasing substrate concentration?', ['Increasing substrate concentration overcomes competitive but not non-competitive inhibition', 'Increasing substrate concentration overcomes both equally', 'Increasing substrate concentration never affects either', 'Increasing substrate concentration worsens both'], 0, 4, 'More substrate outcompetes a competitive inhibitor for the active site.'),
                $this->q('Fibrous proteins such as collagen are structurally suited to their function because they:', ['Are soluble and globular', 'Form long, strong, often insoluble structural fibres', 'Always act as enzymes', 'Are found only in the nucleus'], 1, 4, 'Fibrous proteins provide mechanical strength as structural fibres.'),
