                $this->q('Which event ensures genetic variation through independent assortment?', ['DNA replication', 'Random alignment of homologous pairs at metaphase I', 'Cytokinesis', 'Formation of the spindle'], 1, 3, 'Random orientation shuffles maternal and paternal chromosomes.'),
