                $this->q('Cytokinesis refers to:', ['Replication of DNA', 'Division of the cytoplasm to form two separate cells', 'Pairing of homologous chromosomes', 'Formation of the spindle'], 1, 2, 'Cytokinesis physically splits the cell into two daughter cells.'),
                $this->q('Meiosis contributes to genetic variation through which two main mechanisms?', ['DNA replication and cytokinesis', 'Crossing over and independent assortment of homologous chromosomes', 'Mitosis and cell growth', 'Apoptosis and mutation only'], 1, 3, 'These two mechanisms shuffle alleles into new combinations.'),
