                $this->q('Which of the following is true of meiosis but not mitosis?', ['It produces two daughter cells', 'It involves two successive divisions producing four haploid daughter cells', 'It occurs in somatic (body) cells', "It doesn't involve chromosome movement"], 1, 3, 'Meiosis I and II together produce four haploid cells, unlike mitosis.'),
                $this->q('Down syndrome (trisomy 21) in humans typically results from:', ['A normal meiotic division', 'Non-disjunction during meiosis, producing a gamete with an extra chromosome 21', 'Mitotic division in skin cells', 'A viral infection'], 1, 4, 'An extra copy of chromosome 21 results from non-disjunction in meiosis.'),
                $this->q('Checkpoints in the cell cycle (e.g. at G1/S or G2/M) mainly function to:', ['Speed up cell division regardless of errors', 'Detect DNA damage or errors and halt the cycle until corrected', 'Prevent all cell division permanently', 'Have no regulatory role'], 1, 4, 'Checkpoints ensure damaged or incomplete DNA is not passed to daughter cells.'),
                $this->q('Uncontrolled cell division due to failure of cell cycle checkpoints is associated with:', ['Apoptosis', 'Cancer (tumour formation)', 'Meiosis only', 'Normal healthy tissue turnover'], 1, 4, 'Loss of checkpoint control allows unchecked, uncontrolled cell division.'),
                $this->q('If a diploid organism has 2n=46 chromosomes, how many chromosomes would be present in each cell after meiosis I but before meiosis II completes?', ['46, as two chromatid pairs', '23, each still consisting of two sister chromatids', '92', '12'], 1, 5, 'Meiosis I halves the chromosome number to 23, each still with two chromatids.'),
                $this->q('Explain why crossing over during prophase I increases genetic variation:', ['It creates entirely new genes not present in either parent', 'It exchanges segments of DNA between homologous chromosomes, creating new combinations of existing alleles', 'It duplicates the entire genome', 'It has no effect on allele combinations'], 1, 5, 'Crossing over recombines existing alleles into new combinations, not new genes.'),
            ],
            'AL-GENETICS' => [
                $this->q("An organism's observable characteristics are called its:", ['Genotype', 'Phenotype', 'Allele', 'Genome'], 1, 1, 'Phenotype is the expressed physical/biochemical trait.'),
                $this->q('In a monohybrid cross between two heterozygotes (Aa x Aa), the expected phenotypic ratio is:', ['1:1', '9:3:3:1', '3:1', '1:2:1'], 2, 2, 'Three dominant phenotype offspring to one recessive.'),
                $this->q('A test cross is used to determine:', ['The sex of an organism', 'Whether an organism is homozygous or heterozygous dominant', 'The number of chromosomes', 'The mutation rate'], 1, 3, 'Crossing with a homozygous recessive reveals the unknown genotype.'),
                $this->q('Genes located close together on the same chromosome are said to be:', ['Independent', 'Linked', 'Codominant', 'Recessive'], 1, 3, 'Linked genes tend to be inherited together.'),
                $this->q('Sickle-cell anaemia is an example of:', ['Codominance', 'Sex linkage', 'Polygenic inheritance', 'Environmental variation'], 0, 4, 'Heterozygotes express both normal and sickle haemoglobin.'),
