                $this->q('An allele that is expressed only when two copies are present is called:', ['Dominant', 'Recessive', 'Codominant', 'Linked'], 1, 1, 'Recessive alleles are masked by a dominant allele when heterozygous.'),
                $this->q('The genetic makeup of an organism is called its:', ['Phenotype', 'Genotype', 'Karyotype', 'Chromatype'], 1, 1, 'Genotype refers to the specific alleles an organism carries.'),
                $this->q('An organism with two identical alleles for a gene is described as:', ['Heterozygous', 'Homozygous', 'Hemizygous', 'Polygenic'], 1, 1, 'Homozygous individuals carry two copies of the same allele.'),
                $this->q("In humans, the gene for a particular blood group has three alleles (I^A, I^B, i); this is an example of:", ['Sex linkage', 'Multiple alleles', 'Codominance only', 'Linkage'], 1, 2, 'A gene with more than two alleles in the population shows multiple allelism.'),
                $this->q('A cross between two organisms homozygous for different alleles of the same gene (e.g. AA x aa) is best described as a:', ['Test cross', 'Monohybrid cross', 'Dihybrid cross', 'Back cross'], 1, 2, 'A monohybrid cross considers inheritance of a single gene.'),
                $this->q('Sex-linked genes in humans are most commonly carried on the:', ['Y chromosome only', 'X chromosome', 'Autosomes only', 'Mitochondrial DNA'], 1, 2, 'Most known sex-linked conditions in humans are X-linked.'),
                $this->q('Haemophilia is a recessive, X-linked condition. A carrier mother (unaffected) and unaffected father could have a son with haemophilia because:', ['Sons inherit their only X chromosome from their mother', 'Sons have two X chromosomes', 'Fathers always pass the condition to sons', 'Haemophilia is autosomal dominant'], 0, 3, "A son's single X chromosome comes from his mother, so he expresses whatever allele she carries."),
                $this->q('A pedigree chart showing a trait skipping generations, appearing only in individuals whose parents are unaffected but related, most likely indicates:', ['A dominant autosomal trait', 'A recessive autosomal trait', 'A Y-linked trait', 'An entirely environmental trait'], 1, 3, 'Recessive traits can skip generations, appearing when both parents carry the allele.'),
                $this->q('The term "polygenic inheritance" refers to a phenotype controlled by:', ['A single gene with two alleles', 'Multiple genes at different loci, each contributing to the phenotype', 'Only the environment', 'Mitochondrial DNA alone'], 1, 3, 'Polygenic traits like height are influenced by many genes together.'),
                $this->q('In codominance, both alleles:', ['Blend to form an intermediate phenotype', 'Are fully and separately expressed in the heterozygous phenotype', 'One is always masked completely', 'Neither is expressed'], 1, 4, 'Codominant alleles are both visible in the phenotype, unlike blending.'),
                $this->q('Continuous variation (e.g. human height) as opposed to discontinuous variation is typically caused by:', ['A single gene with complete dominance', 'Multiple genes (polygenic) and environmental influence', 'Sex linkage only', 'Chromosomal mutation only'], 1, 4, 'Continuous traits result from many genes plus environmental effects.'),
                $this->q('A chi-squared (χ²) test is used in genetics to:', ['Directly change allele frequencies', 'Determine whether observed offspring ratios differ significantly from expected ratios', 'Replace the need for Punnett squares entirely', 'Measure mutation rate directly'], 1, 4, 'Chi-squared tests check if observed data fits the expected genetic ratio.'),
                $this->q('In a dihybrid cross where two genes are linked (located close together on the same chromosome), the offspring ratio would most likely:', ['Match the standard 9:3:3:1 ratio exactly', 'Deviate from 9:3:3:1, with parental combinations more frequent than recombinants', 'Always be 1:1:1:1', 'Show no offspring at all'], 1, 5, 'Linked genes are inherited together more often, skewing the expected ratio.'),
                $this->q('Explain why recessive X-linked conditions are more common in males than females:', ['Males have two X chromosomes', 'Males need only one copy of the recessive allele (being hemizygous) to express the condition, while females need two', 'Females cannot carry X-linked alleles', 'The condition is actually Y-linked'], 1, 5, 'Males are hemizygous for X-linked genes, so one recessive allele is enough to show the trait.'),
            ],
            'AL-MOLECULAR-GENETICS' => [
