                $this->q('The sugar found in DNA is:', ['Ribose', 'Deoxyribose', 'Glucose', 'Fructose'], 1, 1, 'Deoxyribose lacks one oxygen atom compared to ribose.'),
                $this->q('DNA is described as antiparallel because its two strands:', ['Run in the same direction', "Run in opposite directions (5' to 3' and 3' to 5')", 'Are identical in sequence', 'Never pair with each other'], 1, 1, 'The two DNA strands run in opposite chemical directions.'),
                $this->q('The process of converting an mRNA sequence into a polypeptide chain is called:', ['Transcription', 'Translation', 'Replication', 'Transformation'], 1, 1, 'Translation at the ribosome builds a protein from mRNA.'),
                $this->q('Which base pairs with adenine in DNA?', ['Guanine', 'Cytosine', 'Thymine', 'Uracil'], 2, 2, 'Adenine pairs with thymine via two hydrogen bonds.'),
                $this->q('RNA differs from DNA in that RNA contains:', ['Deoxyribose and thymine', 'Ribose and uracil (instead of thymine)', 'No nitrogenous bases', 'A double helix always'], 1, 2, 'RNA uses ribose sugar and uracil instead of thymine.'),
                $this->q('The enzyme that joins Okazaki fragments together during DNA replication is:', ['DNA polymerase', 'DNA ligase', 'Helicase', 'RNA polymerase'], 1, 2, 'DNA ligase seals nicks between Okazaki fragments on the lagging strand.'),
                $this->q('Introns differ from exons in that introns:', ['Code for proteins', 'Are non-coding sequences removed during mRNA processing (splicing)', 'Are found only in prokaryotes', 'Are translated directly'], 1, 3, 'Introns are spliced out before mature mRNA leaves the nucleus.'),
                $this->q('The genetic code is described as "degenerate" because:', ['Each amino acid has only one possible codon', 'Most amino acids can be coded for by more than one codon', 'The code differs between all species', 'It cannot be read by ribosomes'], 1, 3, 'Degeneracy means multiple codons can specify the same amino acid.'),
                $this->q('Translation occurs at the:', ['Nucleus', 'Ribosome', 'Golgi apparatus', 'Mitochondrial membrane only'], 1, 3, 'Ribosomes are the site where mRNA is translated into protein.'),
                $this->q('A frameshift mutation (insertion or deletion of one base) typically has a more severe effect than a substitution mutation because it:', ['Only changes one amino acid', 'Shifts the reading frame, altering all subsequent codons', 'Never affects the protein', 'Always improves protein function'], 1, 4, 'Frameshifts alter every codon downstream of the mutation.'),
                $this->q('Which of the following best describes the role of a promoter region in a gene?', ['It codes for the final protein product', 'It is the DNA sequence where RNA polymerase binds to initiate transcription', 'It terminates translation', 'It splices out introns'], 1, 4, 'The promoter is where transcription of a gene begins.'),
                $this->q('Alternative splicing of pre-mRNA allows:', ['A single gene to produce only one possible protein', 'A single gene to produce multiple different protein variants from different exon combinations', 'DNA replication to occur faster', 'Ribosomes to translate DNA directly'], 1, 4, 'Alternative splicing increases protein diversity from a single gene.'),
                $this->q('A mutation changes a codon from coding for an amino acid to a stop codon; this is called a:', ['Silent mutation', 'Nonsense mutation, likely producing a shortened, non-functional protein', 'Missense mutation only', 'Neutral mutation with no effect'], 1, 5, 'Nonsense mutations introduce a premature stop codon, truncating the protein.'),
                $this->q('Explain why a substitution mutation is sometimes described as "silent":', ['It always changes the protein produced', 'Due to the degeneracy of the genetic code, the new codon may still code for the same amino acid, leaving the protein unchanged', 'It stops translation entirely', 'It only affects non-coding DNA'], 1, 5, 'Degeneracy means some base changes don\'t alter the resulting amino acid.'),
            ],
            'AL-HOMEOSTASIS' => [
