                $this->q('Shivering generates heat mainly through:', ['Increased respiration in the liver', 'Rapid, involuntary muscle contractions generating heat', 'Sweating', 'Vasodilation'], 1, 2, 'Muscle contractions during shivering release heat as a by-product.'),
