                $this->q('Osmoreceptors in the hypothalamus detect changes in:', ['Blood glucose concentration', 'Blood water potential (osmotic concentration)', 'Blood oxygen concentration', 'Blood pH only'], 1, 3, 'Osmoreceptors monitor the concentration of the blood plasma.'),
                $this->q('If blood glucose concentration falls too low, the pancreas responds by secreting:', ['Insulin', 'Glucagon, which raises blood glucose', 'ADH', 'Adrenaline exclusively'], 1, 3, 'Glucagon raises blood glucose by promoting glycogen breakdown.'),
