                $this->q('In Type 1 diabetes, the underlying cause is usually:', ['Cells becoming resistant to insulin', 'Autoimmune destruction of insulin-producing beta cells in the pancreas', 'Excess glucagon secretion only', 'A high-sugar diet exclusively'], 1, 4, 'Type 1 diabetes results from the immune system destroying beta cells.'),
                $this->q('The negative feedback loop controlling blood glucose relies on the pancreas acting as both:', ['Effector and receptor only', 'A receptor (detecting glucose level) and effector (secreting hormones)', 'Only an effector', 'Neither receptor nor effector'], 1, 4, 'The pancreas senses glucose levels and responds by secreting hormones.'),
                $this->q('Explain why the hypothalamus is considered central to thermoregulation:', ['It directly produces heat', 'It contains thermoreceptors and coordinates effector responses (sweating, shivering, vasodilation/constriction) to maintain core temperature', 'It has no role in temperature control', 'It only controls blood glucose'], 1, 5, 'The hypothalamus both senses temperature and triggers corrective responses.'),
                $this->q('A person exercising intensely in hot weather would need to lose heat through:', ['Vasoconstriction and reduced sweating', 'Vasodilation and increased sweating, aided by evaporative cooling', 'Shivering', 'Increased insulin secretion'], 1, 5, 'Sweating and vasodilation both increase heat loss during exercise in heat.'),
