                $this->q('The myelin sheath increases the speed of nerve impulses by:', ['Increasing ion channel density', 'Enabling saltatory conduction between nodes of Ranvier', 'Slowing depolarisation', 'Preventing synaptic transmission'], 1, 3, 'Impulses jump between nodes rather than travelling continuously.'),
