                $this->q('A drug that blocks acetylcholinesterase at the synapse would most likely:', ['Have no effect on transmission', 'Prolong the effect of acetylcholine, causing continuous stimulation', 'Immediately stop all nerve transmission', 'Increase resting potential'], 1, 5, 'Without breakdown, acetylcholine keeps stimulating the postsynaptic membrane.'),
