                $this->q('A neuron that carries impulses from the CNS to an effector is called a:', ['Sensory neuron', 'Motor neuron', 'Relay neuron', 'Interneuron only'], 1, 1, 'Motor neurons carry signals from the CNS to muscles or glands.'),
