                $this->q('The refractory period following an action potential ensures that:', ['Impulses travel in one direction only and cannot immediately re-fire', 'Impulses can travel in both directions simultaneously', 'The neuron is permanently inactive', 'The membrane potential never changes again'], 0, 2, 'The refractory period prevents the impulse from travelling backwards.'),
                $this->q('Summation at a synapse allows:', ['A single small stimulus to always trigger a response', 'Multiple sub-threshold stimuli to combine and potentially reach threshold for an action potential', 'Neurotransmitters to be destroyed instantly', 'Synapses to work without neurotransmitters'], 1, 3, 'Summation combines small signals so they can together reach threshold.'),
                $this->q('Which best explains why synapses only transmit impulses in one direction?', ['Neurotransmitter receptors are only present on the postsynaptic membrane', 'Ion channels are identical on both sides', 'Action potentials can travel backward through synapses', 'There is no functional reason'], 0, 3, 'Receptors on only one side ensure one-way transmission.'),
                $this->q('The role of calcium ions at the presynaptic terminal is to:', ['Repolarise the membrane', 'Trigger the fusion of synaptic vesicles with the presynaptic membrane, releasing neurotransmitter', 'Destroy neurotransmitter', 'Open sodium channels on the postsynaptic membrane directly'], 1, 3, 'Calcium influx causes vesicles to fuse and release their neurotransmitter.'),
                $this->q('Multiple sclerosis, a disease that damages the myelin sheath, would most likely cause:', ['Faster nerve conduction', 'Slower or disrupted nerve impulse conduction', 'No change in nervous function', 'Increased hormone secretion'], 1, 4, 'Losing myelin disrupts saltatory conduction, slowing impulses.'),
                $this->q('Inhibitory postsynaptic potentials (IPSPs) function by:', ['Depolarising the postsynaptic membrane, making an action potential more likely', 'Hyperpolarising the postsynaptic membrane, making an action potential less likely', 'Always triggering an action potential', 'Destroying the presynaptic neuron'], 1, 4, 'IPSPs make the membrane more negative, reducing the chance of firing.'),
                $this->q('Compared to the endocrine system, the nervous system typically produces responses that are:', ['Slower and more general', 'Rapid and localised/precise', 'Identical in every way', 'Only chemical, never electrical'], 1, 4, 'Nervous responses are fast and precisely targeted.'),
                $this->q('Explain why saltatory conduction along a myelinated axon is faster than conduction along a non-myelinated axon:', ['The impulse travels continuously along every part of the membrane in both cases', 'The impulse "jumps" between unmyelinated nodes of Ranvier, skipping the insulated sections', 'Myelin actively speeds up ion pumps', 'Myelinated axons are always shorter'], 1, 5, 'Jumping between nodes speeds up impulse conduction considerably.'),
