                $this->q('Allopatric speciation typically involves:', ['Speciation without any geographic separation', 'Geographic isolation of populations, leading to independent evolution and eventual reproductive isolation', 'Instant creation of a new species within one generation', 'Only artificial selection'], 1, 3, 'Geographic separation allows populations to diverge into separate species.'),
