    }

    private function q(string $stem, array $options, int $correctIndex, int $difficulty, string $explanation): array
    {
        $letters = ['A', 'B', 'C', 'D'];
        $keyed = array_combine(array_slice($letters, 0, count($options)), $options);

        return [
            'stem' => $stem,
            'options' => $keyed,
            'correct' => $letters[$correctIndex],
            'difficulty' => $difficulty,
            'explanation' => $explanation,
        ];
    }
}
